from pathlib import Path
import re

path = Path('jeu-vampires-de-sarrebruck/index.html')
text = path.read_text(encoding='utf-8')

block = r'''
<!-- V5.73 — tutoriel interactif "Première nuit" -->
<style id="v573-first-night-tutorial">
#vampTutorialOverlay{position:fixed;inset:0;z-index:100000;background:radial-gradient(circle at 50% 20%,rgba(91,18,28,.35),rgba(2,3,7,.96) 48%,#020307 100%);display:flex;align-items:center;justify-content:center;padding:18px;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#f8efe2}
#vampTutorialOverlay.hidden{display:none!important}
.vt-card{position:relative;width:min(94vw,760px);max-height:92vh;overflow:auto;border:1px solid #8a6336;border-radius:24px;background:linear-gradient(180deg,#171017 0%,#0a0c12 56%,#07090d 100%);box-shadow:0 26px 90px #000,0 0 0 1px #e7bd7120 inset;padding:22px}
.vt-kicker{text-align:center;text-transform:uppercase;letter-spacing:.18em;color:#cfa75e;font-size:.72rem;font-weight:900;margin-bottom:6px}
.vt-title{margin:0;text-align:center;font-family:Georgia,"Times New Roman",serif;color:#fff0d0;font-size:clamp(1.6rem,6vw,2.55rem);line-height:1.05;text-shadow:0 2px 12px #000}
.vt-text{margin:14px auto 0;max-width:620px;text-align:center;color:#e8e0d6;font-size:1rem;line-height:1.48}
.vt-actions{display:grid;gap:10px;margin:18px 0 4px}.vt-actions.three{grid-template-columns:repeat(3,1fr)}
.vt-action{border:1px solid #62515b;border-radius:16px;padding:13px 11px;background:#14151b;color:#f9eddf;text-align:center;box-shadow:inset 0 1px 0 #ffffff10}.vt-action strong{display:block;font-size:1rem;margin-bottom:4px}.vt-action small{display:block;color:#cfc8c2;line-height:1.3}
.vt-action.attack{border-color:#a8343b;background:linear-gradient(180deg,#51141a,#251015)}.vt-action.regen{border-color:#35815a;background:linear-gradient(180deg,#16472f,#10271e)}.vt-action.discard{border-color:#755db1;background:linear-gradient(180deg,#35245f,#1e1739)}
.vt-symbol-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:18px 0}.vt-symbol{display:grid;grid-template-columns:66px 1fr;gap:12px;align-items:center;padding:11px;border-radius:16px;background:#11141b;border:1px solid #343946;text-align:left}.vt-symbol .vt-copy b{display:block;color:#fff0d2;margin-bottom:3px}.vt-symbol .vt-copy span{display:block;color:#d3d0cc;font-size:.9rem;line-height:1.3}
.vt-badge{width:62px;height:62px;display:block;filter:drop-shadow(0 5px 8px #0008)}
.vt-progress{display:flex;justify-content:center;gap:5px;margin:16px 0 2px}.vt-dot{width:7px;height:7px;border-radius:50%;background:#554852}.vt-dot.on{background:#d8ae63;box-shadow:0 0 8px #d8ae6380}
.vt-footer{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:18px}.vt-btn{appearance:none;border:1px solid #745f4a;border-radius:999px;background:#1a1718;color:#f4e8d7;padding:12px 18px;min-height:48px;font-weight:800;font-size:.96rem;cursor:pointer}.vt-btn.primary{border-color:#b6843d;background:linear-gradient(180deg,#8d5a22,#5a3518);color:#fff5df;box-shadow:0 8px 20px #0007}.vt-btn.ghost{border-color:#454956;background:#101217;color:#d4d7dd}.vt-btn:active{transform:translateY(1px)}
.vt-mini{margin:18px 0 4px;border:1px solid #4a3e40;border-radius:20px;overflow:hidden;background:linear-gradient(180deg,#10131a,#090b0f)}.vt-mini-hud{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:10px;padding:14px;background:#0b0d12;border-bottom:1px solid #2e3038}.vt-fighter{text-align:center;font-weight:900;color:#f2e6d5}.vt-fighter .blood{display:block;margin-top:5px;color:#d95558;font-weight:800;letter-spacing:.08em}.vt-vs{color:#9c8b78;font:900 .85rem Georgia,serif}.vt-arena{padding:17px;text-align:center;min-height:155px;display:flex;flex-direction:column;align-items:center;justify-content:center}.vt-arena-title{font:900 1.25rem Georgia,serif;color:#f5e4c4;margin-bottom:6px}.vt-arena-copy{max-width:520px;color:#d8d4cf;line-height:1.4}.vt-choice-row{display:flex;gap:9px;justify-content:center;flex-wrap:wrap;margin-top:14px}.vt-choice{border:1px solid #636a77;border-radius:12px;background:#171b23;color:#eee5d9;padding:10px 14px;font-weight:800;cursor:pointer}.vt-choice.good{border-color:#9d6d33;background:#5b3518}.vt-choice.defend{border-color:#54759e;background:#1e3550}
.vt-tip{margin:14px auto 0;max-width:620px;padding:10px 12px;border-radius:12px;background:#17131a;border:1px solid #4d3747;color:#e6d8cc;text-align:center;font-size:.9rem}.vt-replay-note{margin-top:12px;text-align:center;color:#a9a5a1;font-size:.82rem}
#vampTutorialReplayBtn{margin-top:8px!important}
@media(max-width:620px){.vt-card{padding:17px 13px;border-radius:20px}.vt-actions.three{grid-template-columns:1fr}.vt-symbol-grid{grid-template-columns:1fr}.vt-symbol{grid-template-columns:58px 1fr}.vt-badge{width:54px;height:54px}.vt-mini-hud{padding:11px 8px}.vt-footer{gap:8px}.vt-btn{width:100%}}
</style>
<script id="v573-first-night-tutorial-script">
(()=>{
'use strict';
const KEY='vampires_sarrebruck_tutoriel_v573';
let bypassEnter=false;
let stepIndex=0;
const $=id=>document.getElementById(id);
const enterBtn=$('enterNightBtn');
if(!enterBtn)return;
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function badge(type,label=''){
 const ring='<circle cx="50" cy="50" r="45" fill="#f4ead5" stroke="#1e1a17" stroke-width="3"/><circle cx="50" cy="50" r="42" fill="none" stroke="#b9893d" stroke-width="4"/>';
 let g='';
 if(type==='lightning')g='<path d="M57 13 29 54h19L39 88l33-47H54z" fill="#111"/>';
 if(type==='swords')g='<g stroke="#111" stroke-width="5" stroke-linecap="round"><path d="M27 24 68 70"/><path d="M73 24 32 70"/><path d="M23 20 34 25 28 32z" fill="#111"/><path d="M77 20 66 25 72 32z" fill="#111"/><path d="M25 76 37 66"/><path d="M75 76 63 66"/></g>';
 if(type==='shield'||type==='shieldOff')g='<path d="M50 19 73 27v21c0 18-9 29-23 38-14-9-23-20-23-38V27z" fill="#111"/>'+(type==='shieldOff'?'<path d="M22 78 78 22" stroke="#f4ead5" stroke-width="9"/><path d="M22 78 78 22" stroke="#111" stroke-width="4"/>':'');
 if(type==='drop'||type==='dropPlus'||type==='dropMinus')g='<path d="M43 18c0 0-18 25-18 43 0 15 10 25 23 25s23-10 23-25c0-18-23-43-23-43z" fill="#111"/>'+(type==='dropPlus'?'<text x="72" y="66" font-size="31" font-weight="900" text-anchor="middle" fill="#111">+</text>':'')+(type==='dropMinus'?'<path d="M23 79 77 25" stroke="#f4ead5" stroke-width="10"/><path d="M23 79 77 25" stroke="#111" stroke-width="4"/><text x="75" y="72" font-size="24" font-weight="900" text-anchor="middle" fill="#111">−</text>':'');
 if(type==='hourglass')g='<g fill="none" stroke="#111" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"><path d="M31 22h38M31 78h38M34 24c0 16 5 20 16 27-11 7-16 12-16 25M66 24c0 16-5 20-16 27 11 7 16 12 16 25"/></g>';
 if(type==='cardPlus'||type==='cardMinus')g='<rect x="27" y="24" width="34" height="49" rx="4" fill="none" stroke="#111" stroke-width="5"/><rect x="34" y="18" width="34" height="49" rx="4" fill="#f4ead5" stroke="#111" stroke-width="4"/>'+(type==='cardPlus'?'<text x="76" y="70" font-size="28" font-weight="900" text-anchor="middle" fill="#111">+</text>':'<path d="M23 79 77 25" stroke="#f4ead5" stroke-width="10"/><path d="M23 79 77 25" stroke="#111" stroke-width="4"/><text x="77" y="72" font-size="23" font-weight="900" text-anchor="middle" fill="#111">−</text>');
 if(label)g+=`<text x="73" y="82" font-size="19" font-weight="900" text-anchor="middle" fill="#111">${esc(label)}</text>`;
 return `<svg class="vt-badge" viewBox="0 0 100 100" aria-hidden="true">${ring}${g}</svg>`;
}
function ensureOverlay(){let o=$('vampTutorialOverlay');if(o)return o;o=document.createElement('div');o.id='vampTutorialOverlay';o.className='hidden';o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.setAttribute('aria-label','Tutoriel Les Vampires de Sarrebruck');o.innerHTML='<div class="vt-card" id="vampTutorialCard"></div>';document.body.appendChild(o);return o;}
function dots(i,total){return `<div class="vt-progress">${Array.from({length:total},(_,n)=>`<span class="vt-dot ${n<=i?'on':''}"></span>`).join('')}</div>`;}
function render(html){const o=ensureOverlay();o.classList.remove('hidden');$('vampTutorialCard').innerHTML=html;requestAnimationFrame(()=>{const b=$('vampTutorialCard').querySelector('button');if(b)b.focus({preventScroll:true});});}
function hide(){const o=$('vampTutorialOverlay');if(o)o.classList.add('hidden');}
function remember(){try{localStorage.setItem(KEY,'1');}catch(_){}}
function continueIntoNight(){remember();hide();bypassEnter=true;try{enterBtn.click();}finally{bypassEnter=false;}}
function skip(){continueIntoNight();}
function welcome(){render(`<div class="vt-kicker">Les Vampires de Sarrebruck</div><h2 class="vt-title">Première nuit ?</h2><p class="vt-text">C’est la première fois que tu joues ? Le tutoriel dure seulement quelques étapes : les symboles essentiels, puis un mini-tour pour voir comment ils fonctionnent.</p><div class="vt-footer"><button class="vt-btn primary" data-welcome="yes">Oui, montre-moi</button><button class="vt-btn ghost" data-welcome="no">Non, je connais déjà</button></div><div class="vt-replay-note">Tu pourras le revoir plus tard depuis l’écran de préparation.</div>`);$('vampTutorialCard').querySelector('[data-welcome="yes"]').onclick=()=>showStep(0);$('vampTutorialCard').querySelector('[data-welcome="no"]').onclick=skip;}
const steps=[
 ()=>`<div class="vt-kicker">1 • Le principe d’un tour</div><h2 class="vt-title">Une seule action</h2><p class="vt-text">À ton tour, choisis <b>une</b> de ces trois actions.</p><div class="vt-actions three"><div class="vt-action attack"><strong>1. ATTAQUER</strong><small>Jouer une carte d’attaque.</small></div><div class="vt-action regen"><strong>2. RÉCUPÉRER</strong><small>Jouer une carte de récupération.</small></div><div class="vt-action discard"><strong>3. DÉFAUSSER</strong><small>Défausser 1 carte et en piocher une nouvelle.</small></div></div><div class="vt-tip">Les cartes de défense servent lorsqu’un adversaire t’attaque.</div>`,
 ()=>`<div class="vt-kicker">2 • Les symboles</div><h2 class="vt-title">Lire une carte d’un coup d’œil</h2><div class="vt-symbol-grid"><div class="vt-symbol">${badge('lightning')}<div class="vt-copy"><b>Éclair</b><span>Effet immédiat : applique l’effet indiqué par la carte.</span></div></div><div class="vt-symbol">${badge('swords')}<div class="vt-copy"><b>Épées croisées</b><span>Carte d’attaque : elle vise un adversaire.</span></div></div><div class="vt-symbol">${badge('shield')}<div class="vt-copy"><b>Bouclier</b><span>L’attaque peut être défendue.</span></div></div><div class="vt-symbol">${badge('shieldOff')}<div class="vt-copy"><b>Bouclier barré</b><span>Défense impossible, sauf avec Lame vorace.</span></div></div></div>`,
 ()=>`<div class="vt-kicker">3 • Le sang</div><h2 class="vt-title">Tes gouttes = ta vie</h2><div class="vt-symbol-grid"><div class="vt-symbol">${badge('drop')}<div class="vt-copy"><b>Goutte</b><span>Elle représente le sang, donc la vie du vampire.</span></div></div><div class="vt-symbol">${badge('dropMinus','1')}<div class="vt-copy"><b>Goutte barrée</b><span>Perte de sang. Le chiffre indique combien de gouttes sont perdues.</span></div></div><div class="vt-symbol">${badge('dropPlus','1')}<div class="vt-copy"><b>Goutte +</b><span>Gain de sang. +1 = gagne 1 goutte.</span></div></div><div class="vt-symbol">${badge('hourglass','1')}<div class="vt-copy"><b>Sablier</b><span>Passe le prochain tour. ×2 signifie deux tours.</span></div></div></div><div class="vt-tip">À 0 goutte de sang, le vampire est éliminé.</div>`,
 ()=>`<div class="vt-kicker">4 • Les cartes en main</div><h2 class="vt-title">Piocher ou perdre des cartes</h2><div class="vt-symbol-grid"><div class="vt-symbol">${badge('cardPlus','2')}<div class="vt-copy"><b>Carte +</b><span>Pioche le nombre de cartes indiqué.</span></div></div><div class="vt-symbol">${badge('cardMinus','1')}<div class="vt-copy"><b>Carte barrée</b><span>Défausse le nombre de cartes indiqué.</span></div></div></div><p class="vt-text">Les chiffres changent selon la carte, mais le symbole reste toujours le même.</p>`,
 ()=>miniChoose(),()=>miniAttack(),()=>miniDefense(),
 ()=>`<div class="vt-kicker">Tutoriel terminé</div><h2 class="vt-title">Tu peux entrer dans la nuit</h2><p class="vt-text">Tu connais l’essentiel : <b>une action par tour</b>, les symboles te donnent l’effet en un regard, et une défense se joue lorsqu’on t’attaque.</p><div class="vt-mini"><div class="vt-mini-hud"><div class="vt-fighter">TOI<span class="blood">🩸🩸🩸🩸🩸</span></div><div class="vt-vs">VS</div><div class="vt-fighter">RÜDIGER<span class="blood">🩸🩸🩸🩸</span></div></div><div class="vt-arena"><div class="vt-arena-title">Mini-tour réussi</div><div class="vt-arena-copy">Rüdiger a perdu une goutte, puis tu as évité sa riposte avec une défense.</div></div></div>`
];
function miniChoose(){return `<div class="vt-kicker">5 • Mini-partie</div><h2 class="vt-title">À toi de jouer</h2><div class="vt-mini"><div class="vt-mini-hud"><div class="vt-fighter">TOI<span class="blood">🩸🩸🩸🩸🩸</span></div><div class="vt-vs">VS</div><div class="vt-fighter">RÜDIGER<span class="blood">🩸🩸🩸🩸🩸</span></div></div><div class="vt-arena"><div class="vt-arena-title">Choisis ton action</div><div class="vt-arena-copy">Pour l’exercice, attaque Rüdiger.</div><div class="vt-choice-row"><button class="vt-choice good" data-mini="attack">⚔ Attaquer</button><button class="vt-choice" data-mini="regen">🩸 Récupérer</button><button class="vt-choice" data-mini="discard">↻ Défausser</button></div></div></div>`;}
function miniAttack(){return `<div class="vt-kicker">6 • Mini-partie</div><h2 class="vt-title">Morsure</h2><div class="vt-mini"><div class="vt-mini-hud"><div class="vt-fighter">TOI<span class="blood">🩸🩸🩸🩸🩸</span></div><div class="vt-vs">VS</div><div class="vt-fighter">RÜDIGER<span class="blood">🩸🩸🩸🩸🩸</span></div></div><div class="vt-arena">${badge('swords')}<div class="vt-arena-title">Carte d’attaque</div><div class="vt-arena-copy">La Morsure affiche aussi une goutte barrée −1 : si elle touche, Rüdiger perd 1 goutte de sang.</div><div class="vt-choice-row"><button class="vt-choice good" data-mini="target">Cibler Rüdiger</button></div></div></div>`;}
function miniDefense(){return `<div class="vt-kicker">7 • Mini-partie</div><h2 class="vt-title">Rüdiger riposte</h2><div class="vt-mini"><div class="vt-mini-hud"><div class="vt-fighter">TOI<span class="blood">🩸🩸🩸🩸🩸</span></div><div class="vt-vs">VS</div><div class="vt-fighter">RÜDIGER<span class="blood">🩸🩸🩸🩸</span></div></div><div class="vt-arena">${badge('shield')}<div class="vt-arena-title">Cette attaque est défendable</div><div class="vt-arena-copy">Le bouclier signifie que tu peux jouer une défense compatible.</div><div class="vt-choice-row"><button class="vt-choice defend" data-mini="defend">🛡 Jouer une défense</button></div></div></div>`;}
function showStep(i){stepIndex=Math.max(0,Math.min(steps.length-1,i));const last=stepIndex===steps.length-1;render(`${steps[stepIndex]()}${dots(stepIndex,steps.length)}<div class="vt-footer">${stepIndex>0&&stepIndex<4?'<button class="vt-btn ghost" data-nav="back">Retour</button>':''}${stepIndex<4?'<button class="vt-btn primary" data-nav="next">Suivant</button>':''}${last?'<button class="vt-btn primary" data-nav="finish">Entrer dans la nuit</button>':''}<button class="vt-btn ghost" data-nav="skip">Passer le tutoriel</button></div>`);const card=$('vampTutorialCard');const next=card.querySelector('[data-nav="next"]');if(next)next.onclick=()=>showStep(stepIndex+1);const back=card.querySelector('[data-nav="back"]');if(back)back.onclick=()=>showStep(stepIndex-1);const sk=card.querySelector('[data-nav="skip"]');if(sk)sk.onclick=skip;const fin=card.querySelector('[data-nav="finish"]');if(fin)fin.onclick=continueIntoNight;const attack=card.querySelector('[data-mini="attack"]');if(attack)attack.onclick=()=>showStep(5);['regen','discard'].forEach(v=>{const b=card.querySelector(`[data-mini="${v}"]`);if(b)b.onclick=()=>{b.textContent='Pour ce tutoriel : attaque Rüdiger';setTimeout(()=>showStep(4),700);};});const target=card.querySelector('[data-mini="target"]');if(target)target.onclick=()=>showStep(6);const defend=card.querySelector('[data-mini="defend"]');if(defend)defend.onclick=()=>showStep(7);}
enterBtn.addEventListener('click',e=>{if(bypassEnter)return;let seen=false;try{seen=localStorage.getItem(KEY)==='1';}catch(_){seen=false;}if(seen)return;e.preventDefault();e.stopImmediatePropagation();welcome();},true);
function addReplayButton(){const q=$('quickGuideBtn');if(!q||$('vampTutorialReplayBtn'))return;const b=document.createElement('button');b.id='vampTutorialReplayBtn';b.type='button';b.className='big';b.textContent='Tutoriel interactif';b.addEventListener('click',()=>showStep(0));q.insertAdjacentElement('afterend',b);}
addReplayButton();new MutationObserver(addReplayButton).observe(document.documentElement,{childList:true,subtree:true});
})();
</script>
<!-- /V5.73 -->
'''
pattern = re.compile(r'<!-- V5\.73 — tutoriel interactif "Première nuit" -->.*?<!-- /V5\.73 -->\s*', re.S)
if pattern.search(text):
    text = pattern.sub(block.strip() + '\n', text, count=1)
else:
    if '</body>' not in text:
        raise SystemExit('Closing body tag not found')
    text = text.replace('</body>', block + '\n</body>', 1)
path.write_text(text, encoding='utf-8')
print('V5.73 tutorial injected')
